mapper.update:
UPDATE account
   SET password_hash = #{passwordHash}, password_algorithm = 'ARGON2ID',
       password_changed_at = #{now},
       session_generation = GREATEST(session_generation, #{sessionGeneration}),
       updated_at = #{now}
 WHERE id = #{accountId}

UPDATE account
   SET status = #{status},
       session_generation = GREATEST(session_generation, #{sessionGeneration}),
       updated_at = #{now}
 WHERE id = #{accountId}

mapper.insert:
INSERT INTO account_membership (id, tenant_id, organization_id, account_id, status, created_at, updated_at)
SELECT #{id}, #{tenantId}, #{organizationId}, account.id, 'ACTIVE', #{now}, #{now}
  FROM account WHERE account.id = #{accountId} AND account.status = 'ACTIVE'

mapper.update:
UPDATE account_membership
   SET status = 'SUSPENDED', updated_at = #{now}
 WHERE tenant_id = #{tenantId} AND id = #{membershipId} AND status = 'ACTIVE'

UPDATE account_membership
   SET status = 'ACTIVE', updated_at = #{now}
 WHERE tenant_id = #{tenantId} AND id = #{membershipId} AND status = 'SUSPENDED'

UPDATE account_tenant_security_state
   SET authorization_generation = GREATEST(authorization_generation, #{generation}), updated_at = #{now}
 WHERE tenant_id = #{tenantId} AND account_id = #{accountId}

mapper.select:
SELECT id, tenant_id, membership_id, resource_type, resource_id, action,
       created_by_account_id, created_at, revoked_by_account_id, revoked_at, revoke_reason
  FROM resource_grant
 WHERE membership_id = #{membershipId} AND resource_type = #{resourceType}
   AND resource_id = #{resourceId} AND action = #{action}
   AND effect = 'ALLOW' AND revoked_at IS NULL

mapper.update:
UPDATE resource_grant
   SET revoked_by_account_id = #{actorAccountId}, revoked_at = #{now}, revoke_reason = #{reason}
 WHERE id = #{grantId} AND effect = 'ALLOW' AND revoked_at IS NULL
